curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "exclude_archived=true&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'incident' in ch['name'].lower():
            print(json.dumps(ch, indent=2))
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST https://slack.com/api/conversations.history -H "Authorization: Bearer <TOKEN>" -d "channel=C_INC&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        if 'reactions' in msg:
            for r in msg['reactions']:
                if r['name'] == 'fire':
                    print(f'Found fire reaction on message ts={msg[\"ts\"]}')
                    print(f'  Users who reacted: {r[\"users\"]}')
                    print(f'  Message: {msg.get(\"text\", \"\")[:100]}')
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST https://slack.com/api/conversations.history -H "Authorization: Bearer <TOKEN>" -d "channel=C_INC&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        has_reactions = 'reactions' in msg
        has_thread = 'thread_ts' in msg
        reply_count = msg.get('reply_count', 0)
        print(f'ts={msg[\"ts\"]} | text={msg.get(\"text\",\"\")[:80]} | reactions={has_reactions} | thread={has_thread} | replies={reply_count}')
        if has_reactions:
            for r in msg['reactions']:
                print(f'  reaction: {r[\"name\"]} by {r[\"users\"]}')
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST https://slack.com/api/search.messages -H "Authorization: Bearer <TOKEN>" -d "query=in:incidents&count=100&sort=timestamp&sort_dir=asc" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    msgs = data.get('messages', {}).get('matches', [])
    print(f'Total: {data.get(\"messages\", {}).get(\"total\", 0)}')
    for msg in msgs:
        print(f'ts={msg[\"ts\"]} | text={msg.get(\"text\",\"\")[:80]}')
        if 'reactions' in msg:
            for r in msg['reactions']:
                print(f'  reaction: {r[\"name\"]} by {r[\"users\"]}')
else:
    print(json.dumps(data, indent=2))
"
